<?php
$u=auth();$t=tenancy_access((int)number($b,'tenancy_id',1),$u);tenant_only($t,$u);if(!in_array($t['status'],['active','notice','pending_verification','ready']))fail('This tenancy cannot place orders.');
$items=$b['items']??[];if(!is_array($items)||count($items)<1||count($items)>50)fail('Choose between 1 and 50 products.');$products=[];$provider=null;$kind=null;$total=0;
foreach($items as $item){$p=one('SELECT c.*,s.kind FROM catalog_products c JOIN service_categories s ON s.id=c.category_id JOIN users u ON u.id=c.provider_id WHERE c.id=? AND c.active=1 AND u.verified_at IS NOT NULL AND u.status="active"',[(int)number($item,'product_id',1)]);if(!$p)fail('Product is not available.');if($provider!==null&&($provider!=$p['provider_id']||$kind!==$p['kind']))fail('Place separate orders for different providers or service types.');$provider=$p['provider_id'];$kind=$p['kind'];if(!in_array($kind,['grocery','installation','moving','maid']))fail('Use the catering subscription form.');$qty=number($item,'quantity',0.1,100);$total+=($p['price']+$p['installation_cost'])*$qty;$products[]=['product_id'=>$p['id'],'quantity'=>$qty,'unit_price'=>$p['price'],'installation_cost'=>$p['installation_cost'],'customization'=>textfield($item,'customization',1000,false)];}
$later=(int)!empty($b['pay_later']);if($kind==='installation'&&$later)fail('Pre-installations must be paid on move-in day; pay later is unavailable.');if($kind!=='grocery'&&$later)fail('Pay later is available for groceries, catering and maintenance.');if($kind!=='installation'&&!in_array($t['status'],['active','notice']))fail('Everyday services require an active tenancy.');
$id=insert('orders',['tenancy_id'=>$t['id'],'user_id'=>$u['id'],'provider_id'=>$provider,'address_id'=>$t['address_id'],'kind'=>$kind,'pay_later'=>$later,'scheduled_at'=>!empty($b['scheduled_at'])?datefield($b,'scheduled_at',true):null,'notes'=>textfield($b,'notes',2000,false)]);foreach($products as $p)insert('order_items',['order_id'=>$id,...$p]);$inv=$later?invoice_for((int)$t['id'],(int)$u['id']):insert('invoices',['tenancy_id'=>$t['id'],'user_id'=>$u['id'],'period'=>date('Y-m-01'),'billing_group'=>'order-'.$id,'due_date'=>$kind==='installation'?$t['start_date']:date('Y-m-d')]);insert('invoice_items',['invoice_id'=>$inv,'kind'=>$kind,'description'=>ucfirst($kind).' order #'.$id,'amount'=>$total,'order_id'=>$id]);notify((int)$provider,'New order received','Order #'.$id.' is ready for your review.','provider');audit($u,'order_placed','orders',$id);$result=['id'=>$id,'total'=>$total];
